content.content:
import json,re,sys,os,collections
subs=json.load(open('subagents.json'))
A=re.compile(sys.argv[1],re.I)   # what they said / ran
B=re.compile(sys.argv[2],re.I)   # what they saw
tiers=set(sys.argv[3].split(','))
res=[]
for o in subs:
    top=max(o['models'],key=o['models'].get) if o['models'] else None
    if top not in tiers: continue
    sawN=0;saidN=0;saw1=None;said1=None
    with open(o['fn'],'rb') as fh:
        for i,l in enumerate(fh):
            if not (A.search(l.decode('utf8','ignore')) or B.search(l.decode('utf8','ignore'))): continue
            try:d=json.loads(l)
            except: continue
            c=d.get('message',{}).get('content')
            if isinstance(c,str): blocks=[{'type':'text','text':c}]
            else: blocks=c or []
            for b in blocks:
                if d.get('type')=='assistant':
                    t=b.get('text') if b.get('type')=='text' else json.dumps(b.get('input')) if b.get('type')=='tool_use' else ''
                    m=A.search(t or '')
                    if m: saidN+=1; said1=said1 or (i,d.get('timestamp'),t[max(0,m.start()-150):m.end()+250].replace('\n',' '))
                elif d.get('type')=='user' and b.get('type')=='tool_result':
                    cc=b.get('content'); 
                    if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if x.get('type')=='text')
                    m=B.search(str(cc))
                    if m: sawN+=1; saw1=saw1 or (i,d.get('timestamp'),str(cc)[max(0,m.start()-150):m.end()+250].replace('\n',' '))
    if sawN or saidN:
        res.append((o['first'],o['tag'],top,o['fn'].split('/')[-1][6:12],sawN,saidN,o['prompt'][:110],saw1,said1))
res.sort()
for r in res:
    print(r[0][:16],r[1],r[2],r[3],'saw=%d said=%d'%(r[4],r[5]),'|',r[6])
    if r[7]: print('    SAW :',r[7][0],r[7][1][11:19],r[7][2][:420])
    if r[8]: print('    SAID:',r[8][0],r[8][1][11:19],r[8][2][:420])
